// FlowKit · Onboarding documental — Parte A: validación y checklist por servicio
// Ajusta estas constantes antes de activar el flujo.
const BASE_URL = 'https://TU-N8N.example.com';
const PORTAL_PATH = '/webhook/flowkit-docs?k=';
const EMPRESA = 'Tu asesoría';

const CHECKLIST = {
  fiscal: [
    ['DNI', 'DNI/NIE del titular', 'SI'],
    ['ESCRITURA', 'Escritura de constitución', 'SI'],
    ['CIF', 'CIF y modelo 036/037', 'SI'],
    ['BANCO', 'Certificado de titularidad bancaria', 'SI'],
    ['LIQUIDACIONES', 'Últimas 4 liquidaciones trimestrales', 'NO'],
    ['RENTA', 'Último modelo 100 del titular', 'NO'],
    ['LIBROS', 'Libros contables del ejercicio anterior', 'NO']
  ],
  laboral: [
    ['CIF', 'DNI/NIE o CIF de la empresa', 'SI'],
    ['CONVENIO', 'Convenio colectivo aplicable', 'SI'],
    ['TC', 'Últimos TC1 y TC2', 'SI'],
    ['CONTRATOS', 'Contratos de los empleados en alta', 'NO'],
    ['CALENDARIO', 'Calendario laboral vigente', 'NO']
  ],
  constitucion: [
    ['DNI_SOCIOS', 'DNI/NIE de todos los socios', 'SI'],
    ['DENOMINACION', 'Certificado de denominación social', 'SI'],
    ['ESTATUTOS', 'Estatutos sociales', 'SI'],
    ['ESCRITURA', 'Escritura de constitución', 'SI'],
    ['CIF', 'CIF provisional', 'SI'],
    ['BANCO', 'Certificado de apertura de cuenta bancaria', 'NO']
  ],
  contable: [
    ['CIF', 'DNI/NIE o CIF del cliente', 'SI'],
    ['PODERES', 'Escrituras o poderes de representación', 'SI'],
    ['BANCOS', 'Extractos bancarios del ejercicio', 'SI'],
    ['FACTURAS', 'Facturas emitidas y recibidas del ejercicio', 'SI'],
    ['INVENTARIO', 'Inventario de existencias', 'NO']
  ],
  general: [
    ['IDENTIDAD', 'DNI/NIE o CIF', 'SI'],
    ['PODERES', 'Escrituras o poderes de representación', 'SI'],
    ['BANCO', 'Certificado de titularidad bancaria', 'SI'],
    ['ESPECIFICA', 'Documentación específica del servicio', 'NO']
  ]
};

const SERVICIOS = {
  'Fiscal y contable': 'fiscal',
  'Laboral (nóminas)': 'laboral',
  'Constitución de sociedad': 'constitucion',
  'Solo contabilidad': 'contable',
  'Otro / a medida': 'general'
};

function pad(n) { return (n < 10 ? '0' : '') + n; }
function iso(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
function norm(s) { return String(s === null || s === undefined ? '' : s).trim().toLowerCase(); }
function val(row, names) {
  const keys = Object.keys(row || {});
  for (let i = 0; i < names.length; i++) {
    for (let j = 0; j < keys.length; j++) {
      if (norm(keys[j]) === norm(names[i])) {
        const v = row[keys[j]];
        return v === null || v === undefined ? '' : v;
      }
    }
  }
  return '';
}
function rid(n) {
  const abc = 'abcdefghijkmnpqrstuvwxyz23456789';
  let s = '';
  for (let i = 0; i < n; i++) s += abc.charAt(Math.floor(Math.random() * abc.length));
  return s;
}

const f = $('Alta de cliente (formulario)').first().json;
const cliente = String(f['Nombre del cliente'] || '').trim();
const email = String(f['Email de contacto'] || '').trim().toLowerCase();
const telefono = String(f['Teléfono'] || '').trim();
const servicioLabel = String(f['Servicio contratado'] || '').trim();
const notas = String(f['Notas internas'] || '').trim();
const servicio = SERVICIOS[servicioLabel] || 'general';
const emailOk = email.indexOf('@') > 0 && email.indexOf('.') > email.indexOf('@') + 1 && email.indexOf(' ') < 0;

if (!cliente) return [{ json: { ok: false, motivo: 'Falta el nombre del cliente.' } }];
if (!emailOk) return [{ json: { ok: false, motivo: 'El email no es válido: ' + String(f['Email de contacto'] || '(vacío)') } }];

const existentes = $input.all().map(function (i) { return i.json; }).filter(function (r) {
  return norm(val(r, ['Email'])) === norm(email);
});
if (existentes.length) {
  return [{ json: {
    ok: false,
    motivo: 'Ese email ya tiene un onboarding abierto (' + (String(val(existentes[0], ['Estado'])) || 'En curso') + ', alta ' + String(val(existentes[0], ['Fecha_alta'])) + '). No se crea un duplicado.',
    cliente: String(val(existentes[0], ['Cliente'])),
    email: email
  } }];
}

const token = rid(10);
const docs = (CHECKLIST[servicio] || CHECKLIST.general).map(function (d) {
  return { codigo: d[0], documento: d[1], obligatorio: d[2] };
});
const hoy = new Date();
hoy.setHours(0, 0, 0, 0);

return [{ json: {
  ok: true,
  cliente: cliente,
  email: email,
  telefono: telefono,
  servicio: servicio,
  servicio_label: servicioLabel || 'Otro / a medida',
  token: token,
  portal: BASE_URL + PORTAL_PATH + token,
  fecha: iso(hoy),
  notas: notas,
  docs: docs,
  total: docs.length,
  obligatorios: docs.filter(function (d) { return d.obligatorio === 'SI'; }).length,
  empresa: EMPRESA
} }];

// FlowKit · Onboarding documental — una fila por documento requerido
const a = $('Validar y preparar checklist').first().json;
const out = [];
for (const d of a.docs) {
  out.push({ json: {
    ID: a.token.slice(0, 5) + '-' + d.codigo,
    Cliente: a.cliente,
    Email: a.email,
    Servicio: a.servicio,
    Documento: d.documento,
    Codigo: d.codigo,
    Obligatorio: d.obligatorio,
    Estado: 'Pendiente',
    Token: a.token,
    Fecha_solicitud: a.fecha,
    Fecha_recibido: '',
    Recordatorios: '0',
    Ultimo_recordatorio: '',
    Nota: ''
  } });
}
return out;

// FlowKit · Onboarding documental — aviso al equipo
const NL = String.fromCharCode(10);
const a = $('Validar y preparar checklist').first().json;
const l = [];
l.push('📥 Nuevo onboarding · ' + a.cliente);
l.push(a.servicio_label + ' · ' + a.total + ' documentos (' + a.obligatorios + ' obligatorios)');
l.push('Email: ' + a.email + (a.telefono ? ' · ' + a.telefono : ''));
l.push('Portal del cliente: ' + a.portal);
if (a.notas) l.push('Nota: ' + a.notas);
l.push('');
l.push('Checklist (ID de cada documento para registrar la entrega):');
for (const d of a.docs) l.push('· ' + a.token.slice(0, 5) + '-' + d.codigo + ' — ' + d.documento + (d.obligatorio === 'SI' ? ' (obligatorio)' : ''));
return [{ json: { text: l.join(NL) } }];

// FlowKit · Onboarding documental — email de bienvenida con la checklist
const NL = String.fromCharCode(10);
const a = $('Validar y preparar checklist').first().json;
const l = [];
l.push('Hola ' + a.cliente + ',');
l.push('');
l.push('Gracias por confiar en ' + a.empresa + '. Para empezar con tu ' + a.servicio_label.toLowerCase() + ' necesitamos esta documentación:');
l.push('');
for (const d of a.docs) l.push('  [ ] ' + d.documento + (d.obligatorio === 'SI' ? ' (obligatorio)' : ' (si lo tienes)'));
l.push('');
l.push('Cómo enviarla: responde a este correo adjuntando los archivos en PDF o foto legible. Puedes consultar el estado en cualquier momento aquí:');
l.push(a.portal);
l.push('');
l.push('En cuanto la recibamos revisamos que esté completa y te lo confirmamos. Si algún documento no lo tienes, dínoslo y buscamos la forma de sustituirlo.');
l.push('');
l.push('Un saludo,');
l.push(a.empresa);
return [{ json: {
  to: a.email,
  subject: 'Documentación para tu alta · ' + a.empresa,
  body: l.join(NL)
} }];

const NL = String.fromCharCode(10);
const e = $json;
const l = [];
l.push('⚠️ Onboarding · alta no creada');
l.push(e.motivo || 'No se ha podido validar el formulario.');
if (e.cliente) l.push('Cliente: ' + e.cliente + (e.email ? ' · ' + e.email : ''));
l.push('Corrige el dato y vuelve a enviar el formulario.');
return [{ json: { text: l.join(NL) } }];

// FlowKit · Onboarding documental — Parte B: seguimiento de documentación pendiente
// Ajusta estas constantes antes de activar el flujo.
const BASE_URL = 'https://TU-N8N.example.com';
const PORTAL_PATH = '/webhook/flowkit-docs?k=';
const EMPRESA = 'Tu asesoría';
const DIAS = [3, 7, 14, 21];
const NL = String.fromCharCode(10);

function pad(n) { return (n < 10 ? '0' : '') + n; }
function iso(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
function mk(y, m, d) {
  const dt = new Date(y, m - 1, d);
  if (dt.getFullYear() !== y || dt.getMonth() !== m - 1 || dt.getDate() !== d) return null;
  return dt;
}
function parseDate(v) {
  if (!v) return null;
  if (v instanceof Date) return isNaN(v.getTime()) ? null : new Date(v.getFullYear(), v.getMonth(), v.getDate());
  let s = String(v).trim();
  if (!s) return null;
  if (s.length >= 10 && s.charAt(4) === '-') {
    const d0 = new Date(s.slice(0, 10) + 'T00:00:00');
    if (!isNaN(d0.getTime())) return new Date(d0.getFullYear(), d0.getMonth(), d0.getDate());
  }
  const p = s.split('/');
  if (p.length === 3) return mk(Number(p[2]), Number(p[1]), Number(p[0]));
  const d1 = new Date(s);
  return isNaN(d1.getTime()) ? null : new Date(d1.getFullYear(), d1.getMonth(), d1.getDate());
}
function norm(s) { return String(s === null || s === undefined ? '' : s).trim().toLowerCase(); }
function val(row, names) {
  const keys = Object.keys(row || {});
  for (let i = 0; i < names.length; i++) {
    for (let j = 0; j < keys.length; j++) {
      if (norm(keys[j]) === norm(names[i])) {
        const v = row[keys[j]];
        return v === null || v === undefined ? '' : v;
      }
    }
  }
  return '';
}
function dias(a, b) { return Math.round((a.getTime() - b.getTime()) / 86400000); }

const HOY = new Date();
HOY.setHours(0, 0, 0, 0);
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) {
  return String(val(r, ['ID'])).trim() !== '';
});

const clientes = {};
for (const r of rows) {
  if (norm(val(r, ['Estado'])) === 'recibido') continue;
  const token = String(val(r, ['Token'])).trim();
  if (!token) continue;
  if (!clientes[token]) {
    clientes[token] = {
      token: token,
      cliente: String(val(r, ['Cliente'])).trim(),
      email: norm(val(r, ['Email'])),
      docs: [],
      solicitud: null,
      ultimo: null,
      recordatorios: 0
    };
  }
  const c = clientes[token];
  c.docs.push({
    ID: String(val(r, ['ID'])).trim(),
    documento: String(val(r, ['Documento'])).trim()
  });
  const fSol = parseDate(val(r, ['Fecha_solicitud']));
  if (fSol && (!c.solicitud || fSol < c.solicitud)) c.solicitud = fSol;
  const uRec = parseDate(val(r, ['Ultimo_recordatorio']));
  if (uRec && (!c.ultimo || uRec > c.ultimo)) c.ultimo = uRec;
  const nRec = Number(val(r, ['Recordatorios']));
  if (!isNaN(nRec) && nRec > c.recordatorios) c.recordatorios = nRec;
}

const out = [];
for (const k in clientes) {
  const c = clientes[k];
  if (c.email.indexOf('@') < 1) continue;
  const dSol = c.solicitud ? dias(HOY, c.solicitud) : 0;
  if (dSol < DIAS[0]) continue;
  if (c.ultimo && dias(HOY, c.ultimo) <= 0) continue;
  let nivel = 0;
  for (const d of DIAS) { if (dSol >= d) nivel++; }
  if (nivel === 0 || c.recordatorios >= nivel) continue;

  const l = [];
  l.push('Hola ' + c.cliente + ',');
  l.push('');
  if (nivel === 1) l.push('Te escribimos para recordarte la documentación pendiente de tu alta en ' + EMPRESA + '.');
  else if (nivel === 2) l.push('Seguimos pendientes de la documentación de tu alta en ' + EMPRESA + '. Sin ella no podemos avanzar con tu expediente.');
  else l.push('Han pasado ' + dSol + ' días desde que solicitamos la documentación de tu alta en ' + EMPRESA + ' y sigue pendiente. Necesitamos recibirla para no seguir retrasando el trabajo.');
  l.push('');
  l.push('Nos falta:');
  for (const d of c.docs) l.push('  [ ] ' + d.documento);
  l.push('');
  l.push('Puedes responder a este correo adjuntando los archivos o consultar el estado aquí:');
  l.push(BASE_URL + PORTAL_PATH + c.token);
  l.push('');
  l.push('Si algún documento no lo tienes, o crees que ya lo enviaste, respóndenos y lo revisamos.');
  l.push('');
  l.push('Gracias,');
  l.push(EMPRESA);

  out.push({ json: {
    tipo: 'recordatorio',
    to: String(c.email),
    subject: (nivel >= 3 ? 'Último aviso: ' : '') + 'Documentación pendiente de tu alta · ' + EMPRESA,
    body: l.join(NL),
    cliente: c.cliente,
    token: c.token,
    nivel: nivel,
    dias: dSol,
    pendientes: c.docs.length,
    docs: c.docs.map(function (d) { return d.ID; })
  } });
}

return out;

// FlowKit · Onboarding documental — marcar los recordatorios que ya han salido
// Si el envío falla, el item no llega aquí y el cliente se reintenta mañana.
const NL = String.fromCharCode(10);
const HOY = new Date();
HOY.setHours(0, 0, 0, 0);
function pad(n) { return (n < 10 ? '0' : '') + n; }
function iso(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
const hoy = iso(HOY);

const items = $input.all().map(function (i) { return i.json; }).filter(function (x) {
  return x && x.tipo === 'recordatorio' && Array.isArray(x.docs) && x.docs.length > 0;
});

const out = [];
for (const e of items) {
  for (const id of e.docs) {
    out.push({ json: { ID: id, Recordatorios: String(e.nivel), Ultimo_recordatorio: hoy } });
  }
}
return out;

// FlowKit · Onboarding documental — resumen del día para el equipo
const NL = String.fromCharCode(10);
const items = $('Clasificar pendientes').all().map(function (i) { return i.json; }).filter(function (x) {
  return x && x.tipo === 'recordatorio';
});
if (!items.length) return [];

const l = [];
l.push('📄 Onboarding · recordatorios enviados hoy (' + items.length + ')');
for (const it of items.slice(0, 25)) {
  l.push('· ' + it.cliente + ' — nivel ' + it.nivel + ', ' + it.dias + ' días, ' + it.pendientes + (it.pendientes === 1 ? ' documento' : ' documentos') + (it.dias >= 21 ? ' ⚠️ valorar llamada' : ''));
  l.push('  ' + it.docs.join(', '));
}
if (items.length > 25) l.push('… y ' + (items.length - 25) + ' clientes más.');
l.push('');
l.push('Para registrar una entrega: formulario «Documentación recibida» con el email del cliente y los IDs.');
return [{ json: { text: l.join(NL) } }];

// FlowKit · Onboarding documental — portal de estado para el cliente
// Solo lectura: el enlace privado (token) muestra qué falta, pero no cambia nada.
function norm(s) { return String(s === null || s === undefined ? '' : s).trim().toLowerCase(); }
function val(row, names) {
  const keys = Object.keys(row || {});
  for (let i = 0; i < names.length; i++) {
    for (let j = 0; j < keys.length; j++) {
      if (norm(keys[j]) === norm(names[i])) {
        const v = row[keys[j]];
        return v === null || v === undefined ? '' : v;
      }
    }
  }
  return '';
}
function esc(s) {
  return String(s === null || s === undefined ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function fechaCorta(v) {
  const s = String(v || '').slice(0, 10);
  const p = s.split('-');
  return p.length === 3 ? p[2] + '/' + p[1] + '/' + p[0] : s;
}
function page(inner) {
  return '<!DOCTYPE html><html lang="es"><head><meta charset="utf-8">'
    + '<meta name="viewport" content="width=device-width, initial-scale=1">'
    + '<title>Documentación · alta de cliente</title>'
    + '<style>body{margin:0;background:#f6f7f9;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1f2937}'
    + '.wrap{max-width:640px;margin:0 auto;padding:32px 20px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:24px}'
    + 'h1{font-size:20px;margin:0 0 4px}p{margin:8px 0;line-height:1.5}.muted{color:#6b7280;font-size:14px}'
    + '.bar{height:10px;background:#e5e7eb;border-radius:99px;overflow:hidden;margin:18px 0 6px}.bar span{display:block;height:100%;background:#2563eb}'
    + 'ul{list-style:none;padding:0;margin:14px 0}li{display:flex;gap:10px;padding:10px 0;border-bottom:1px solid #f1f5f9;font-size:15px}'
    + '.ok{color:#059669;font-weight:700}.pend{color:#d97706;font-weight:700}'
    + '.tag{font-size:11px;text-transform:uppercase;letter-spacing:.04em;background:#eff6ff;color:#1d4ed8;border-radius:99px;padding:2px 8px}'
    + '.footer{margin-top:18px;font-size:12px;color:#9ca3af}</style></head>'
    + '<body><div class="wrap"><div class="card">' + inner + '</div></div></body></html>';
}

const q = $('Portal de documentación').first().json.query || {};
const token = String(q.k || '').trim();
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) {
  return String(val(r, ['ID'])).trim() !== '';
});
const del = token ? rows.filter(function (r) { return String(val(r, ['Token'])).trim() === token; }) : [];

if (!del.length) {
  return [{ json: { ok: false, html: page('<h1>Enlace no válido</h1><p class="muted">Este enlace no existe o ha caducado. Pide uno nuevo a tu asesoría.</p>') } }];
}

const cliente = String(val(del[0], ['Cliente'])).trim();
const servicio = String(val(del[0], ['Servicio'])).trim();
const ETIQUETAS = {
  fiscal: 'Fiscal y contable',
  laboral: 'Laboral (nóminas)',
  constitucion: 'Constitución de sociedad',
  contable: 'Contabilidad',
  general: 'Asesoramiento'
};
let recibidos = 0;
const filas = [];
for (const r of del) {
  const ok = norm(val(r, ['Estado'])) === 'recibido';
  if (ok) recibidos++;
  const obligatorio = String(val(r, ['Obligatorio'])).toUpperCase() === 'SI';
  filas.push('<li><span class="' + (ok ? 'ok' : 'pend') + '">' + (ok ? '✔' : '○') + '</span><span>'
    + esc(val(r, ['Documento']))
    + (obligatorio ? ' <span class="tag">obligatorio</span>' : '')
    + (ok ? '<br><span class="muted">Recibido el ' + fechaCorta(val(r, ['Fecha_recibido'])) + '</span>' : '')
    + '</span></li>');
}
const total = del.length;
const pct = total ? Math.round((recibidos / total) * 100) : 0;

const inner = '<h1>Documentación de tu alta</h1>'
  + '<p class="muted">' + esc(cliente) + ' · ' + esc(ETIQUETAS[servicio] || servicio || 'Asesoramiento') + '</p>'
  + '<div class="bar"><span style="width:' + pct + '%"></span></div>'
  + '<p class="muted">' + recibidos + ' de ' + total + ' documentos recibidos (' + pct + '%)</p>'
  + '<ul>' + filas.join('') + '</ul>'
  + '<p class="muted">Para enviar los documentos pendientes, responde al correo donde recibiste este enlace y adjúntalos en PDF o foto legible. No hace falta que crees ninguna cuenta.</p>'
  + '<p class="footer">Enlace privado: no lo compartas. Si crees que es un error, contacta con tu asesoría.</p>';

return [{ json: { ok: true, html: page(inner) } }];

// FlowKit · Onboarding documental — Parte D: registrar documentos recibidos
const NL = String.fromCharCode(10);
function norm(s) { return String(s === null || s === undefined ? '' : s).trim().toLowerCase(); }
function val(row, names) {
  const keys = Object.keys(row || {});
  for (let i = 0; i < names.length; i++) {
    for (let j = 0; j < keys.length; j++) {
      if (norm(keys[j]) === norm(names[i])) {
        const v = row[keys[j]];
        return v === null || v === undefined ? '' : v;
      }
    }
  }
  return '';
}
function pad(n) { return (n < 10 ? '0' : '') + n; }
function iso(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }

const f = $('Registrar documentación recibida').first().json;
const email = norm(f['Email del cliente']);
const nota = String(f['Nota'] || '').trim().slice(0, 300);
const entrada = String(f['Documentos recibidos'] || '')
  .split(/[\s,;]+/)
  .map(function (t) { return t.trim(); })
  .filter(function (t) { return t !== ''; });

if (email.indexOf('@') < 1) return [{ json: { ok: false, motivo: 'Falta el email del cliente.' } }];
if (!entrada.length) return [{ json: { ok: false, motivo: 'No has indicado ningún documento recibido.' } }];

const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) {
  return String(val(r, ['ID'])).trim() !== '';
});
const delCliente = rows.filter(function (r) { return norm(val(r, ['Email'])) === email; });
if (!delCliente.length) {
  return [{ json: { ok: false, motivo: 'No hay ningún onboarding con el email ' + email + '. Revisa que coincida con el de la hoja Onboarding.' } }];
}

const pendientes = delCliente.filter(function (r) { return norm(val(r, ['Estado'])) !== 'recibido'; });
const todos = delCliente;
const byId = {};
const byCodigo = {};
for (const r of pendientes) {
  byId[norm(val(r, ['ID']))] = r;
  const cod = norm(val(r, ['Codigo']));
  if (cod && !byCodigo[cod]) byCodigo[cod] = r;
}

const elegidos = [];
const noEncontrados = [];
const yaRecibidos = [];
for (const t of entrada) {
  const k = norm(t);
  const r = byId[k] || byCodigo[k] || null;
  if (r) {
    if (elegidos.indexOf(r) < 0) elegidos.push(r);
    continue;
  }
  const ya = todos.some(function (x) { return norm(val(x, ['ID'])) === k || norm(val(x, ['Codigo'])) === k; });
  if (ya) { if (yaRecibidos.indexOf(t) < 0) yaRecibidos.push(t); }
  else if (noEncontrados.indexOf(t) < 0) noEncontrados.push(t);
}

if (!elegidos.length) {
  return [{ json: {
    ok: false,
    motivo: 'Ninguno de los documentos indicados está pendiente para este cliente.',
    no_encontrados: noEncontrados,
    ya_recibidos: yaRecibidos
  } }];
}

const hoy = iso(new Date());
const cliente = String(val(todos[0], ['Cliente'])).trim();
const total = todos.length;
const recibidosAntes = total - pendientes.length;
const recibidosAhora = recibidosAntes + elegidos.length;
const completo = recibidosAhora >= total;

const updates = elegidos.map(function (r) {
  return { ID: String(val(r, ['ID'])).trim(), Estado: 'Recibido', Fecha_recibido: hoy, Nota: nota };
});

return [{ json: {
  ok: true,
  cliente: cliente,
  email: email,
  token: String(val(todos[0], ['Token'])).trim(),
  ids: elegidos.map(function (r) { return String(val(r, ['ID'])).trim(); }),
  docs: elegidos.map(function (r) { return String(val(r, ['Documento'])).trim(); }),
  updates: updates,
  total: total,
  recibidos_ahora: recibidosAhora,
  completo: completo,
  no_encontrados: noEncontrados,
  ya_recibidos: yaRecibidos,
  nota: nota,
  fecha: hoy
} }];

