// FlowKit · Onboarding documental — Parte E: informe semanal
const NL = String.fromCharCode(10);
const HOY = new Date();
HOY.setHours(0, 0, 0, 0);
function pad(n) { return (n < 10 ? '0' : '') + n; }
function iso(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
function fecha(d) { return pad(d.getDate()) + '/' + pad(d.getMonth() + 1) + '/' + d.getFullYear(); }
function mk(y, m, d) {
  const dt = new Date(y, m - 1, d);
  if (dt.getFullYear() !== y || dt.getMonth() !== m - 1 || dt.getDate() !== d) return null;
  return dt;
}
function parseDate(v) {
  if (!v) return null;
  if (v instanceof Date) return isNaN(v.getTime()) ? null : new Date(v.getFullYear(), v.getMonth(), v.getDate());
  let s = String(v).trim();
  if (!s) return null;
  if (s.length >= 10 && s.charAt(4) === '-') {
    const d0 = new Date(s.slice(0, 10) + 'T00:00:00');
    if (!isNaN(d0.getTime())) return new Date(d0.getFullYear(), d0.getMonth(), d0.getDate());
  }
  const p = s.split('/');
  if (p.length === 3) return mk(Number(p[2]), Number(p[1]), Number(p[0]));
  const d1 = new Date(s);
  return isNaN(d1.getTime()) ? null : new Date(d1.getFullYear(), d1.getMonth(), d1.getDate());
}
function norm(s) { return String(s === null || s === undefined ? '' : s).trim().toLowerCase(); }
function val(row, names) {
  const keys = Object.keys(row || {});
  for (let i = 0; i < names.length; i++) {
    for (let j = 0; j < keys.length; j++) {
      if (norm(keys[j]) === norm(names[i])) {
        const v = row[keys[j]];
        return v === null || v === undefined ? '' : v;
      }
    }
  }
  return '';
}
function dias(a, b) { return Math.round((a.getTime() - b.getTime()) / 86400000); }

const onboarding = $('Leer onboarding (informe)').all().map(function (i) { return i.json; }).filter(function (r) {
  return String(val(r, ['Email'])).trim() !== '';
});
const docs = $('Leer documentos (informe)').all().map(function (i) { return i.json; }).filter(function (r) {
  return String(val(r, ['ID'])).trim() !== '';
});

const porToken = {};
for (const d of docs) {
  const t = String(val(d, ['Token'])).trim();
  if (!t) continue;
  if (!porToken[t]) porToken[t] = { pend: 0, total: 0, min: null };
  const e = porToken[t];
  e.total++;
  if (norm(val(d, ['Estado'])) !== 'recibido') {
    e.pend++;
    const f = parseDate(val(d, ['Fecha_solicitud']));
    if (f && (!e.min || f < e.min)) e.min = f;
    const label = String(val(d, ['Documento'])).trim() || String(val(d, ['Codigo'])).trim();
    if (label) {
      if (!porToken['_doc_' + label]) porToken['_doc_' + label] = 0;
      porToken['_doc_' + label]++;
    }
  }
}

let enCurso = 0;
let completos = 0;
let completos30 = 0;
let bloqueados = 0;
let sumaDias = 0;
let sinEmail = 0;
const bloqueadosLista = [];
const enCursoLista = [];

for (const r of onboarding) {
  const email = String(val(r, ['Email'])).trim();
  const estado = norm(val(r, ['Estado']));
  const cliente = String(val(r, ['Cliente'])).trim() || '(sin nombre)';
  if (email.indexOf('@') < 1) sinEmail++;
  if (estado === 'completo') {
    completos++;
    const fc = parseDate(val(r, ['Fecha_completo']));
    if (fc && dias(HOY, fc) <= 30 && dias(HOY, fc) >= 0) completos30++;
    continue;
  }
  enCurso++;
  const alta = parseDate(val(r, ['Fecha_alta']));
  const dAlta = alta ? dias(HOY, alta) : 0;
  sumaDias += dAlta > 0 ? dAlta : 0;
  const t = String(val(r, ['Token'])).trim();
  const info = porToken[t] || { pend: 0, total: Number(val(r, ['Docs_total'])) || 0 };
  if (info.pend > 0 && dAlta >= 21) {
    bloqueados++;
    bloqueadosLista.push('· ' + cliente + ' — ' + info.pend + ' pendientes, ' + dAlta + ' días desde el alta');
  } else {
    enCursoLista.push('· ' + cliente + ' — ' + info.pend + '/' + info.total + ' pendientes, ' + dAlta + ' días');
  }
}

const totalCli = enCurso + completos;
const tasa = totalCli ? Math.round((completos / totalCli) * 100) : 0;

const l = [];
l.push('📊 Onboarding · informe semanal (' + fecha(HOY) + ')');
l.push('');
l.push('En curso: ' + enCurso + ' · Completos: ' + completos + ' · Tasa de finalización: ' + tasa + '%');
l.push('Completados en los últimos 30 días: ' + completos30);
if (enCurso) l.push('Antigüedad media de los expedientes abiertos: ' + Math.round(sumaDias / enCurso) + ' días');
l.push('');
if (bloqueados) {
  l.push('⚠️ Bloqueados (+21 días): ' + bloqueados);
  for (const b of bloqueadosLista.slice(0, 10)) l.push(b);
  if (bloqueadosLista.length > 10) l.push('… y ' + (bloqueadosLista.length - 10) + ' más');
  l.push('');
}
if (enCursoLista.length) {
  l.push('Abiertos sin bloquear:');
  for (const e of enCursoLista.slice(0, 10)) l.push(e);
  if (enCursoLista.length > 10) l.push('… y ' + (enCursoLista.length - 10) + ' más');
  l.push('');
}

const atascados = Object.keys(porToken)
  .filter(function (k) { return k.indexOf('_doc_') === 0; })
  .map(function (k) { return [k.slice(5), porToken[k]]; })
  .sort(function (a, b) { return b[1] - a[1]; })
  .slice(0, 3);
if (atascados.length) {
  l.push('Documentos que más se atascan:');
  for (const a of atascados) l.push('· ' + a[0] + ' — ' + a[1] + ' pendientes');
}
if (sinEmail) {
  l.push('');
  l.push('Revisar: ' + sinEmail + (sinEmail === 1 ? ' cliente sin email (no recibe avisos).' : ' clientes sin email (no reciben avisos).'));
}
if (!onboarding.length) {
  l.push('Todavía no hay clientes en la hoja Onboarding.');
}
return [{ json: { text: l.join(NL) } }];

